package com.aistock.scheduler.task;
import java.time.*;import java.sql.Timestamp;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.stereotype.Repository;
@Repository public class VerificationScanRepository {
 private final JdbcTemplate jdbc;private final TaskRepository tasks;private final TransactionTemplate tx;
 public VerificationScanRepository(JdbcTemplate jdbc,TaskRepository tasks){this.jdbc=jdbc;this.tasks=tasks;tx=new TransactionTemplate(new DataSourceTransactionManager(Objects.requireNonNull(jdbc.getDataSource())));tx.setTimeout(5);}
 public Cursor cursor(LocalDate cutoff,Instant now){return tx.execute(t->{jdbc.update("insert into verification_scan(plan_id,cutoff_date,revision,updated_at) values(1,?,0,?) on duplicate key update plan_id=plan_id",cutoff,Timestamp.from(now));var row=locked();if(row.cutoffDate().isBefore(cutoff)){jdbc.update("update verification_scan set cutoff_date=?,after_id=null,revision=revision+1,updated_at=? where plan_id=1",cutoff,Timestamp.from(now));return locked();}return row;});}
 public boolean publish(Cursor cursor,PredictionTaskClient.Page page,Instant now){validate(cursor,page);return Boolean.TRUE.equals(tx.execute(t->{var current=locked();if(current.revision()!=cursor.revision()||!current.cutoffDate().equals(cursor.cutoffDate())||!Objects.equals(current.afterId(),cursor.afterId()))return false;for(var item:page.items())tasks.createVerification(item.predictionId(),item.instrumentId(),item.dueThrough(),item.ruleVersion(),TaskRepository.verificationKey(item),now);jdbc.update("update verification_scan set after_id=?,revision=revision+1,updated_at=? where plan_id=1",page.nextCursor(),Timestamp.from(now));return true;}));}
 private void validate(Cursor cursor,PredictionTaskClient.Page page){if(page==null||!cursor.cutoffDate().equals(page.cutoffDate())||page.items().size()>50)throw new IllegalArgumentException("Invalid verification scan page");String previous=cursor.afterId()==null?"":cursor.afterId();for(var item:page.items()){if(item.predictionId()==null||item.predictionId().compareTo(previous)<=0||item.dueThrough()==null||item.dueThrough().isAfter(cursor.cutoffDate()))throw new IllegalArgumentException("Invalid verification scan order");previous=item.predictionId();}if(page.nextCursor()!=null&&(page.items().isEmpty()||!page.nextCursor().equals(previous)))throw new IllegalArgumentException("Invalid verification scan cursor");}
 private Cursor locked(){return jdbc.queryForObject("select cutoff_date,after_id,revision from verification_scan where plan_id=1 for update",(r,n)->new Cursor(r.getDate(1).toLocalDate(),r.getString(2),r.getLong(3)));}
 public record Cursor(LocalDate cutoffDate,String afterId,long revision){}
}
